'use strict';
const $=id=>document.getElementById(id);
const state={data:null,view:'overview',compound:null,mapCompound:null,threshold:120,ec50Range:'all',busy:false,repeatOptions:{},includeReference:false,study:'EXP26007301',instrument:null,sourceParameters:null,normalization:null,layoutAudit:null,cypa:null};
const colors=['#2465CB','#9760AE','#24897A','#CE822C','#D45772','#6B73A8'];
const titles={overview:'Activity overview',curves:'Dose–response curves',map:'Compound map',results:'Parameters & hits',layoutAudit:'Verified plate assignments',sourceReport:'Source parameter report',normalizationAudit:'GDS normalization check',instrumentReadings:'Instrument readings',cypaDependency:'CypA inhibitor comparison',plateQC:'Raw plate QC',repeatQC:'Technical replicate review',methods:'Analysis methods'};
const esc=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const fmt=(v,d=2)=>v==null||!Number.isFinite(Number(v))?'—':Number(v).toLocaleString('en-US',{maximumFractionDigits:d});
const sig=v=>v==null?'—':Number(v).toPrecision(3).replace(/\.0+(?=e|$)/,'');
const color=t=>colors[state.data.targets.indexOf(t)%colors.length];
const cmaxActive=q=>q.cmax>state.threshold;
const ec50Category=q=>AtlasPotency.category(q);
const ec50Matches=q=>AtlasPotency.matches(q,state.ec50Range);
const ecRangeLabel=q=>AtlasPotency.labels[ec50Category(q)];
const active=q=>cmaxActive(q)&&ec50Matches(q);
function activityRule(){return `Cmax > ${fmt(state.threshold)}`+(state.ec50Range==='all'?'':` and reported EC50 ${AtlasPotency.labels[state.ec50Range]}`);}
function activityStatus(q){if(!cmaxActive(q))return 'Below Cmax cutoff';if(state.ec50Range==='all'||ec50Matches(q))return 'Active';const cat=ec50Category(q);return cat==='unreported'?'EC50 not reported':cat==='unresolved'?'EC50 unresolved':'Outside EC50 range';}
const analysisCurves=()=>state.data.curves.filter(q=>state.includeReference||!q.is_reference);
const analysisCompounds=()=>state.data.compounds.filter(c=>analysisCurves().some(q=>q.compound===c));
const curvesFor=c=>state.data.curves.filter(q=>q.compound===c);
let serial=0;
function svg(w,h,body,title){return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(title)}"><title>${esc(title)}</title><style>text{font-family:Arial,sans-serif;font-size:11px;fill:#60718a}.strong-label{fill:#172b45;font-weight:600}.axis-title{font-size:11px;fill:#60718a}.gridline{stroke:#e5eaf1;stroke-width:1}</style>${body}</svg>`;}
function txt(x,y,text,attrs=''){return `<text x="${x}" y="${y}" ${attrs}>${esc(text)}</text>`;}
function line(x1,y1,x2,y2,stroke='#e5eaf1',attrs=''){return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${stroke}" ${attrs}/>`;}
function tip(text){return `data-tip="${esc(text)}"`;}
function range(values,pad=.08){let lo=Math.min(...values),hi=Math.max(...values);if(lo===hi){lo-=1;hi+=1;}return [lo-(hi-lo)*pad,hi+(hi-lo)*pad];}
function linear(domain,extent){return v=>extent[0]+(v-domain[0])/(domain[1]-domain[0])*(extent[1]-extent[0]);}
function measure(id,min=300){return Math.max(min,$(id).clientWidth||min);}
function niceStep(span,n=5){const raw=span/n,power=10**Math.floor(Math.log10(raw)),frac=raw/power;return (frac<=1?1:frac<=2?2:frac<=5?5:10)*power;}
function ticks(domain,n=5){let step=niceStep(domain[1]-domain[0],n),out=[];for(let v=Math.ceil(domain[0]/step)*step;v<=domain[1]+step/100;v+=step)out.push(+v.toPrecision(10));return out;}
function status(message,error=false){$('status').hidden=!message;$('status').textContent=message;$('status').classList.toggle('error',error);$('status').setAttribute('role',error?'alert':'status');}
function busy(value){state.busy=value;for(const id of ['analyze','analyzePaste','demo','pdfSelected','pdfAll','exportActive','exportResults','studySelect'])$(id).disabled=value;$('analyze').textContent=value?'Analyzing…':'Analyze files';}
async function request(url,body){const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(!r.ok){const e=await r.json();throw new Error(e.error||'Request failed');}return r;}
function base64(bytes){let s='';const a=new Uint8Array(bytes);for(let i=0;i<a.length;i+=32768)s+=String.fromCharCode(...a.subarray(i,i+32768));return btoa(s);}
async function runAnalysis(files){if(state.busy)return;busy(true);status('Fitting corrected responses and building activity maps. This may take a few seconds…');try{const data=await AtlasClient.analyze(files,message=>status(message));if(files.some(f=>/EXP26003438.*CyclinD1/i.test(f.name)))await setStudyProfile('EXP26003438');load(data);status('Analysis complete. Activity calls use the Cmax definition shown above.');}catch(e){status(e.message,true);}finally{busy(false);}}
function load(data){state.data=data;state.repeatOptions={};$('includeReference').checked=state.includeReference;const modes=[...new Set(data.curves.map(q=>q.report?.source_mode).filter(Boolean))].sort();$('sourceMode').innerHTML='<option value="">All source classifications</option>'+modes.map(m=>`<option>${esc(m)}</option>`).join('');$('referenceToggle').hidden=!data.curves.some(q=>q.is_reference);$('referenceNote').textContent=data.curves.some(q=>q.is_reference)?'Library summaries exclude the positive reference unless included above. All curves and all-parameter exports retain it.':'';state.compound=data.compounds[0];state.mapCompound=data.compounds[0];const opts=data.compounds.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');$('compound').innerHTML=opts;$('compoundNames').innerHTML=data.compounds.map(c=>`<option value="${esc(c)}"></option>`).join('');$('compoundSearch').value=state.compound;$('mapCompound').innerHTML=opts;$('targetFilter').innerHTML='<option value="">All targets</option>'+data.targets.map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');$('search').value='';$('datasetLabel').textContent=`${data.compounds.length} compounds · ${data.targets.length} targets · ${fmt(data.wells_total,0)} corrected wells · ${data.files.length} source file${data.files.length===1?'':'s'}`;$('footerStats').textContent=`${data.curves.length} compound–target curves`;render();}
function setView(name){document.querySelector('main').classList.toggle('focused-view',name!=='overview');state.view=name;for(const id of Object.keys(titles))$(id).hidden=id!==name;document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===name);b.setAttribute('aria-current',b.dataset.view===name?'page':'false');});$('pageTitle').textContent=titles[name];if(state.data)renderView();$('tooltip').hidden=true;$('pageTitle').scrollIntoView({block:'start'});}
function chooseCompound(compound,target){state.compound=compound;$('compound').value=compound;$('compoundSearch').value=compound;setView('curves');if(target){setTimeout(()=>{const el=document.querySelector(`[data-target-name="${CSS.escape(target)}"]`);if(el)el.scrollIntoView({behavior:'smooth',block:'center'});},40);}}
function render(){if(!state.data)return;const d=state.data,bases=d.cmax_bases;$('basisNote').textContent=bases.length===1?(bases[0]==='Reported Activity (cmax)'?'Activity uses the analyzer’s reported Activity (cmax). Source QC flags remain visible.':'Corrected wells only: activity uses the maximum observed dose mean. Add the parameter export to use reported Activity (cmax).'):'Mixed Cmax definitions: some pairs use reported Activity (cmax), others use observed peak dose mean. Check the Basis column before comparing.';const unknown=d.curves.filter(q=>ec50Category(q)==='unreported').length,unresolved=d.curves.filter(q=>ec50Category(q)==='unresolved').length;$('filterNote').textContent=state.ec50Range==='all'?'Hit rule: '+activityRule()+'. Choose an EC50 range to add a potency criterion. Reported values are used; refits stay separate.':'Hit rule: '+activityRule()+'. '+unknown+' pairs have no reported EC50; '+unresolved+' have unresolved bounds. These do not meet a selected EC50 range.';renderView();renderMethods();}
function renderView(){({overview:renderOverview,curves:renderCurves,map:renderMap,results:renderResults,plateQC:()=>AtlasQCView.render({data:state.data,host:'plateQC'}),repeatQC:()=>AtlasRepeatReview.render({data:state.data,hostId:'repeatReview',cmaxThreshold:state.threshold,...state.repeatOptions,onOptionsChange:o=>Object.assign(state.repeatOptions,o)}),cypaDependency:renderCypaDependency,layoutAudit:renderLayoutAudit,sourceReport:renderSourceParameters,normalizationAudit:renderNormalizationAudit,instrumentReadings:renderInstrumentReadings,methods:renderMethods}[state.view])();}
async function renderCypaDependency(){const host=$('cypaDependency');if(state.study!=='EXP26003438'){host.innerHTML='<section class="panel">The matched inhibitor comparison belongs to EXP26003438. Select that experiment above.</section>';return;}if(!state.cypa){host.innerHTML='<section class="panel">Loading paired biological replicate curves…</section>';try{const r=await fetch('./cypa-dependency.json');if(!r.ok)throw new Error('CypA comparison data unavailable.');state.cypa=await r.json();}catch(e){host.textContent=e.message;return;}}if(!state.sourceParameters){try{const r=await fetch('./cyclind1-source-parameters.json');if(r.ok)state.sourceParameters=await r.json();}catch(e){state.sourceParameters=[];}}if(state.view==='cypaDependency')AtlasCypAView.render({hostId:'cypaDependency',data:state.cypa,sourceParameters:state.sourceParameters||[],compound:state.cypa.compounds.some(c=>c.compound===state.compound)?state.compound:undefined});}
function renderOverview(){const d=state.data,aq=analysisCurves(),ac=analysisCompounds(),hits=aq.filter(active),unique=new Set(hits.map(q=>q.compound)),counts=d.targets.map(t=>({target:t,total:aq.filter(q=>q.target===t).length,n:hits.filter(q=>q.target===t).length})).sort((a,b)=>b.n-a.n||a.target.localeCompare(b.target));const lead=counts.filter(q=>q.n===counts[0].n).map(q=>q.target).join(' / ');$('metrics').innerHTML=[['Compounds in summaries',ac.length,`${d.targets.length} targets measured`],['Active on any target',unique.size,`${fmt(unique.size/ac.length*100,1)}% of compounds`],['Active compound–target pairs',hits.length,`of ${aq.length} measured pairs`],['Most active compounds',lead,`${counts[0].n} hits${counts.filter(q=>q.n===counts[0].n).length>1?' · tied leaders':''}`]].map((r,i)=>`<div class="metric ${i===3?'highlight':''}"><div class="metric-label">${esc(r[0])}</div><div class="metric-value" ${i===3?'style="font-size:21px;line-height:1.35"':''}>${esc(r[1])}</div><div class="metric-note">${esc(r[2])}</div></div>`).join('');
 const w=measure('ranking'),h=Math.max(235,counts.length*46+65),left=100,right=75,top=17,max=Math.max(...counts.map(q=>q.total),1),x=linear([0,max],[left,w-right]);let b='';
 for(const tick of ticks([0,max],4)){b+=line(x(tick),top,x(tick),h-45);b+=txt(x(tick),h-27,tick,'text-anchor="middle"');}
 counts.forEach((q,i)=>{const y=top+i*46;b+=txt(left-12,y+19,q.target,'text-anchor="end" class="strong-label"');b+=`<rect x="${left}" y="${y+5}" width="${w-right-left}" height="22" rx="4" fill="#edf1f6"/><rect x="${left}" y="${y+5}" width="${Math.max(0,x(q.n)-left)}" height="22" rx="4" fill="${color(q.target)}" ${tip(`${q.target}: ${q.n} active of ${q.total}; ${fmt(q.n/q.total*100,1)}%`)}/>`;b+=txt(w-right+12,y+20,`${q.n} / ${q.total}`,'class="strong-label"');});b+=txt((left+w-right)/2,h-6,'Number of active compounds','text-anchor="middle" class="axis-title"');$('ranking').innerHTML=svg(w,h,b,'Target ranking by active compound count');renderOverlap();renderHeatmap();renderPotencySummary();renderSourceSummary();}
function renderPotencySummary(){const bands=[...AtlasPotency.ranges,'unreported','unresolved'];let out='<table class="potency-table"><thead><tr><th>Target</th>'+bands.map(k=>`<th class="num ${state.ec50Range===k?'selected-band':''}">${esc(AtlasPotency.labels[k])}</th>`).join('')+'</tr></thead><tbody>';for(const t of state.data.targets){const qs=analysisCurves().filter(q=>q.target===t&&cmaxActive(q));out+=`<tr><th>${esc(t)}</th>`+bands.map(k=>`<td class="num ${state.ec50Range===k?'selected-band':''}">${qs.filter(q=>ec50Category(q)===k).length}</td>`).join('')+'</tr>';}out+='</tbody></table>';$('potencySummary').innerHTML=out;}
function renderOverlap(){const d=state.data,t=d.targets,by=new Map();analysisCompounds().forEach(c=>{const qs=curvesFor(c),mask=t.map(target=>qs.some(q=>q.target===target&&active(q))?'1':'0').join('');const v=by.get(mask)||[];v.push(c);by.set(mask,v);});const pats=[...by].sort((a,b)=>b[1].length-a[1].length).slice(0,12),w=measure('overlap'),left=91,top=23,barH=105,gap=(w-left-10)/Math.max(pats.length,1),max=Math.max(...pats.map(p=>p[1].length),1),height=barH+68+t.length*23;let b='';
 for(const tick of ticks([0,max],3)){const y=top+barH-tick/max*barH;b+=line(left,y,w-8,y);b+=txt(left-8,y+4,tick,'text-anchor="end"');}
 pats.forEach(([mask,names],i)=>{const x=left+gap*(i+.5),bh=names.length/max*barH;const label=t.filter((_,j)=>mask[j]==='1').join(' + ')||'None';b+=`<rect x="${x-Math.min(18,gap*.32)}" y="${top+barH-bh}" width="${Math.min(36,gap*.64)}" height="${bh}" rx="3" fill="#5478ae" ${tip(`${label}: ${names.length} compounds\n${names.join(', ')}`)}/>`;b+=txt(x,top+barH-bh-7,names.length,'text-anchor="middle" class="strong-label"');let ys=[];t.forEach((target,j)=>{const y=top+barH+43+j*23;if(mask[j]==='1')ys.push(y);b+=`<circle cx="${x}" cy="${y}" r="${mask[j]==='1'?4.5:3}" fill="${mask[j]==='1'?'#496b9e':'#e0e6ef'}" ${tip(`${label}: ${names.length} compounds`)}/>`;});if(ys.length>1)b+=line(x,Math.min(...ys),x,Math.max(...ys),'#496b9e','stroke-width="1.5"');if(mask.indexOf('1')<0)b+=txt(x,top+barH+25,'None','text-anchor="middle" style="font-size:9px"');});t.forEach((target,j)=>{b+=txt(left-10,top+barH+47+j*23,target,'text-anchor="end"');});b+=txt(left-35,top-10,'Count','text-anchor="middle"');$('overlap').innerHTML=svg(w,height,b,'Counts of compounds in each exact active-target combination');}
function heatStyle(v){const values=state.data.curves.map(q=>q.cmax),hi=Math.max(150,...values),lo=Math.min(80,...values);if(v<100){let a=Math.min(1,(100-v)/(100-lo));return {bg:`rgb(${Math.round(244-a*6)},${Math.round(246-a*78)},${Math.round(248-a*124)})`,fg:'#563b29'};}const a=Math.min(1,(v-100)/(hi-100));return {bg:`rgb(${Math.round(244-a*196)},${Math.round(246-a*139)},${Math.round(248-a*44)})`,fg:a>.63?'#fff':'#1c3b62'};}
function isSourceFlagged(q){const r=q.report||{};return !!r.source_qc||r.exclude_from_reporting||q.report&&r.source_valid!=='yes';}
function renderHeatmap(){const d=state.data,mode=$('heatMode').value,order=$('heatOrder').value;let names=analysisCompounds();if(order==='cluster')names=d.cluster_order.filter(c=>analysisCompounds().includes(c));else if(order==='activity')names.sort((a,b)=>curvesFor(b).filter(active).length-curvesFor(a).filter(active).length||a.localeCompare(b));let b=`<table class="heatmap-table"><thead><tr><th>Compound</th>${d.targets.map(t=>`<th style="text-align:center">${esc(t)}</th>`).join('')}<th class="num">Hits</th></tr></thead><tbody>`;for(const c of names){const qs=curvesFor(c);b+=`<tr><td><button class="compound-link" data-compound="${esc(c)}">${esc(c)}</button></td>`;for(const t of d.targets){const q=qs.find(q=>q.target===t);if(!q){b+='<td style="text-align:center">—</td>';continue;}const hs=heatStyle(q.cmax),is=active(q),qc=isSourceFlagged(q);const cat=ec50Category(q),bandStyle={le1:['#d9eee7','#176451'],one3:['#e6edff','#355a9c'],three10:['#fbefda','#895b20'],gt10:['#eee6f5','#705184'],unreported:['#f0f2f6','#60718a'],unresolved:['#f0f2f6','#60718a']}[cat];const bg=mode==='ec50'?bandStyle[0]:mode==='binary'?(is?'#d8e9ff':'#f0f2f6'):hs.bg,fg=mode==='ec50'?bandStyle[1]:mode==='binary'?(is?'#215796':'#60718a'):hs.fg;const label=`${c} / ${t}: Cmax ${fmt(q.cmax,4)}, ${activityStatus(q)}. Reported EC50 ${ecText(q)}; range ${ecRangeLabel(q)}. ${q.cmax_basis}${qc?'. Source QC flagged.':''}`;b+=`<td><button data-compound="${esc(c)}" data-target="${esc(t)}" style="background:${bg};color:${fg}" title="${esc(label)}" aria-label="${esc(label)}">${mode==='ec50'?esc(ecRangeLabel(q)):mode==='binary'?(is?'Active':esc(activityStatus(q))):fmt(q.cmax,1)}${qc?'<span class="qc-dot">•</span>':''}</button></td>`;}b+=`<td class="num">${qs.filter(active).length} / ${qs.length}</td></tr>`;}b+='</tbody></table>';$('heatmap').innerHTML=b;$('heatLegend').innerHTML=mode==='ec50'?`<span>Reported EC50 (µM): ≤1 · >1–3 · >3–10 · >10</span><span>Missing or unresolved bounds are labeled separately</span><span>• Source QC flag</span>`:mode==='binary'?`<span>Active: ${esc(activityRule())}</span><span>• Source QC issue or Valid not marked yes</span>`:'<span>Lower response</span><span class="gradient"></span><span>Higher response</span><span>100 = neutral color reference</span><span>• Source QC flag</span>';}
function responseDomain(qs){const vals=[state.threshold,0];for(const q of qs){for(const s of q.doses){vals.push(...s.wells,s.mean+(s.sd||0),s.mean-(s.sd||0));}}const lo=Math.min(0,...vals),hi=Math.max(...vals);return [lo<0?lo-(hi-lo)*.05:0,hi+Math.max(10,(hi-lo)*.07)];}
function curvePlot(q,w,domain,residual=false){const ss=q.doses.filter(s=>s.x>0),h=residual?190:290,left=58,right=15,top=15,bottom=45;if(!ss.length)return '<div class="empty">No positive doses for a log-axis plot.</div>';const xd=range(ss.map(s=>Math.log10(s.x)),.025),x=linear(xd,[left,w-right]);let yd=domain,means=ss.map(s=>[s.x,s.mean]);
 const predicted=dose=>{if(!q.fit)return null;const f=q.fit;return f.s0+(f.sinf-f.s0)/(1+(f.ec50/dose)**f.hill);};if(residual){if(!q.fit)return '<div class="empty">Residuals require a fitted curve.</div>';const vals=ss.flatMap(s=>s.wells.map(y=>y-predicted(s.x))),max=Math.max(10,...vals.map(Math.abs))*1.15;yd=[-max,max];means=ss.map(s=>[s.x,s.mean-predicted(s.x)]);}
 const y=linear(yd,[h-bottom,top]),id=`clip${++serial}`,c=color(q.target);let b=`<defs><clipPath id="${id}"><rect x="${left}" y="${top}" width="${w-right-left}" height="${h-bottom-top}"/></clipPath></defs>`;
 for(const tick of ticks(yd,5)){b+=line(left,y(tick),w-right,y(tick));b+=txt(left-9,y(tick)+4,fmt(tick,1),'text-anchor="end"');}
 let xt=[];for(let z=Math.ceil(xd[0]);z<=Math.floor(xd[1]);z++)xt.push(z);if(xt.length<2)xt=[Math.log10(ss[0].x),Math.log10(ss[ss.length-1].x)];if(w<430&&xt.length>4)xt=xt.filter((_,i)=>i%2===0);for(const z of [...new Set(xt)]){b+=txt(x(z),h-bottom+19,sig(10**z),'text-anchor="middle"');b+=line(x(z),h-bottom,x(z),h-bottom+4,'#bdc8d8');}
 b+=txt((left+w-right)/2,h-7,'Concentration (µM, log scale)','text-anchor="middle" class="axis-title"');b+=`<text transform="translate(13 ${(top+h-bottom)/2}) rotate(-90)" text-anchor="middle" class="axis-title">${residual?'Residual (response units)':'Corrected response'}</text>`;
 b+=`<g clip-path="url(#${id})">`;b+=line(left,y(residual?0:state.threshold),w-right,y(residual?0:state.threshold),'#96a4b6','stroke-dasharray="4 4"');
 if(!residual&&q.fit)b+=`<path d="${q.fit.line.map(([dose,v],i)=>`${i?'L':'M'}${x(Math.log10(dose)).toFixed(2)},${y(v).toFixed(2)}`).join(' ')}" fill="none" stroke="${c}" stroke-width="1.6" stroke-dasharray="5 3"/>`;
 b+=`<path d="${means.map(([dose,v],i)=>`${i?'L':'M'}${x(Math.log10(dose)).toFixed(2)},${y(v).toFixed(2)}`).join(' ')}" fill="none" stroke="${c}" stroke-width="1.8"/>`;
 ss.forEach((s,i)=>{const px=x(Math.log10(s.x)),mean=means[i][1],py=y(mean);if(!residual&&s.sd!=null){b+=line(px,y(mean-s.sd),px,y(mean+s.sd),c);b+=line(px-3,y(mean-s.sd),px+3,y(mean-s.sd),c);b+=line(px-3,y(mean+s.sd),px+3,y(mean+s.sd),c);}if($('showWells').checked)s.wells.forEach((v,j)=>{const vy=residual?v-predicted(s.x):v;b+=`<circle cx="${px+((j%3)-1)*2.5}" cy="${y(vy)}" r="2.2" fill="#fff" stroke="${c}" opacity=".8" ${tip(`${q.target} at ${sig(s.x)} µM: well ${fmt(v,3)}${residual?', residual '+fmt(vy,3):''}`)}/>`;});b+=`<circle cx="${px}" cy="${py}" r="3.3" fill="${c}" ${tip(`${q.target} at ${sig(s.x)} µM: mean ${fmt(s.mean,3)}; SD ${fmt(s.sd,3)}; n=${s.n}`)}/>`;});b+='</g>';return svg(w,h,b,`${q.compound}, ${q.target}: ${residual?'4PL residuals':'corrected dose response'}`);}
function ecText(q){const r=q.report;if(r&&r.ec50!=null)return `${r.qualifier} ${sig(r.ec50)} µM`;return 'Not reported';}
function renderCurves(){const qs=curvesFor(state.compound),hits=qs.filter(active);$('curveSummary').textContent=`${state.compound} · Active on ${hits.length} of ${qs.length} tested targets${hits.length?': '+hits.map(q=>q.target).join(', '):''}.`;$('curveGrid').innerHTML=qs.map((q,i)=>{const f=q.fit,r=q.report||{},flag=q.fit_flags.join(' · ');return `<section class="curve-card" data-target-name="${esc(q.target)}"><div class="curve-top"><h2 style="color:${color(q.target)}">${esc(q.target)}</h2><span class="pill ${active(q)?'':'neutral'}">${esc(activityStatus(q))}</span></div><div class="curve-numbers"><span>Cmax <b>${fmt(q.cmax,1)}</b></span><span>Reported EC50 <b>${esc(ecText(q))}</b></span><span>EC50 range <b>${esc(ecRangeLabel(q))}</b></span></div><div id="curve-${i}" class="plot"></div><div class="curve-numbers"><span>Refit EC50 <b>${f?sig(f.ec50)+' µM':'—'}</b></span><span>Hill <b>${f?fmt(f.hill):'—'}</b></span><span>R² <b>${f?fmt(f.r2,3):'—'}</b></span></div><div class="fit-flags ${flag?'':'good'}">${esc(flag||'Fit within range; inspect source QC.')}</div><div class="source-flags">Plate group: ${esc(q.transfection)} · Original export label: ${esc(q.source_transfection||q.transfection)}<br>${esc(q.curve_note||'')}<br>Cmax basis: ${esc(q.cmax_basis)}<br>Source QC: ${esc(r.source_qc||'none')} · Valid: ${esc(r.source_valid||'not reported')} · ${q.n_wells} included wells${q.excluded_wells?' · '+q.excluded_wells+' excluded':''}</div>${$('residuals').checked?`<h3 style="font-size:11px;font-weight:550;color:#60718a;margin:17px 0 3px">Residuals: observed − fitted</h3><div id="resid-${i}" class="plot"></div>`:''}<details class="dose-table"><summary>Dose values and fit parameters</summary><p>S0 ${f?fmt(f.s0):'—'} · Sinf ${f?fmt(f.sinf):'—'} · Amplitude ${f?fmt(f.amplitude):'—'} · RMSE ${f?fmt(f.rmse):'—'}</p><table><thead><tr><th>Dose (µM)</th><th class="num">Mean</th><th class="num">SD</th><th class="num">N</th><th>Wells</th></tr></thead><tbody>${q.doses.map(s=>`<tr><td>${sig(s.x)}</td><td class="num">${fmt(s.mean)}</td><td class="num">${fmt(s.sd)}</td><td class="num">${s.n}</td><td>${s.wells.map(v=>fmt(v)).join(', ')}</td></tr>`).join('')}</tbody></table></details><button class="export-svg" data-plot="curve-${i}" style="margin-top:13px">Export curve SVG</button></section>`;}).join('');const shared=responseDomain(qs);qs.forEach((q,i)=>{const w=measure(`curve-${i}`);$(`curve-${i}`).innerHTML=curvePlot(q,w,$('sharedScale').checked?shared:responseDomain([q]));if($('residuals').checked)$(`resid-${i}`).innerHTML=curvePlot(q,w,null,true);});}
function renderMap(){const single=state.data.targets.length===1;$('mapTitle').textContent=single?(state.data.cmax_bases.includes('Observed peak dose mean')?'Independent fit potency and observed response':'Reported potency and response'):'Compound response similarity';$('mapDescription').textContent=single?'Single-assay potency versus response. Corrected-only data uses independent 4PL EC50 and observed peak means; reported parameters are used when matched.':'PCA of standardized Cmax profiles. Nearby points have similar measured responses.';if(single)renderPotencyMap();else renderPCA();renderFingerprint();renderCorrelation();}
function renderPCA(){const d=state.data,p=d.pca,w=measure('pca'),h=390;if(!p.points.length){$('pca').innerHTML=`<div class="empty">${esc(p.reason)}</div>`;$('pcaNote').textContent='';return;}const left=57,right=20,top=23,bottom=54,xdom=range(p.points.map(p=>p.x),.2),ydom=range(p.points.map(p=>p.y),.2),x=linear(xdom,[left,w-right]),y=linear(ydom,[h-bottom,top]);let b='';for(const tick of ticks(xdom,5)){b+=line(x(tick),top,x(tick),h-bottom);b+=txt(x(tick),h-bottom+18,fmt(tick,1),'text-anchor="middle"');}for(const tick of ticks(ydom,5)){b+=line(left,y(tick),w-right,y(tick));b+=txt(left-10,y(tick)+4,fmt(tick,1),'text-anchor="end"');}if(ydom[0]<0&&ydom[1]>0)b+=line(left,y(0),w-right,y(0),'#bdcbdc');if(xdom[0]<0&&xdom[1]>0)b+=line(x(0),top,x(0),h-bottom,'#bdcbdc');
 const scale=.65*Math.min(Math.max(...p.points.map(p=>Math.abs(p.x))),Math.max(...p.points.map(p=>Math.abs(p.y))));
 if(xdom[0]<0&&xdom[1]>0&&ydom[0]<0&&ydom[1]>0)p.loadings.forEach(l=>{const xx=x(l.x*scale),yy=y(l.y*scale);b+=line(x(0),y(0),xx,yy,color(l.target),'opacity=".38" stroke-width="1.5"');b+=txt(xx+4,yy-6,l.target,`style="fill:${color(l.target)};font-size:10px"`);});
 p.points.forEach(pt=>{const qs=curvesFor(pt.compound),hits=qs.filter(active),best=[...qs].sort((a,b)=>b.cmax-a.cmax)[0],selected=pt.compound===state.mapCompound;const fill=hits.length?color(best.target):'#adb8c8',radius=selected?7.5:5;b+=`<circle cx="${x(pt.x)}" cy="${y(pt.y)}" r="${radius}" fill="${fill}" stroke="${selected?'#172b45':'#fff'}" stroke-width="${selected?2:1.5}" data-map-compound="${esc(pt.compound)}" tabindex="0" role="button" aria-label="Select ${esc(pt.compound)}" ${tip(`${pt.compound}\n${hits.length} active targets; highest response: ${best.target} (${fmt(best.cmax,1)})`)}/>`;if(selected){const rightward=x(pt.x)<w*.64;b+=txt(x(pt.x)+(rightward?12:-12),y(pt.y)-10,pt.compound,`text-anchor="${rightward?'start':'end'}" class="strong-label" style="font-size:10px"`);}});b+=txt((left+w-right)/2,h-8,`PC1 (${fmt(p.variance[0]*100,1)}% of profile variance)`,'text-anchor="middle" class="axis-title"');b+=`<text transform="translate(13 ${(top+h-bottom)/2}) rotate(-90)" text-anchor="middle" class="axis-title">PC2 (${fmt(p.variance[1]*100,1)}%)</text>`;$('pca').innerHTML=svg(w,h,b,'PCA compound map of standardized target response profiles');$('mapLegend').innerHTML=d.targets.map(t=>`<span><i class="legend-dot" style="background:${color(t)}"></i>${esc(t)}</span>`).join('')+'<span><i class="legend-dot" style="background:#adb8c8"></i>No target meets selected criteria</span>';$('pcaNote').textContent=`${p.points.length} complete compound profiles mapped; ${p.excluded} excluded for missing target values. Click a point to inspect its fingerprint. Arrows show target directions, scaled for display. Criteria affect highlighting; PCA coordinates still use all complete Cmax profiles.`;}
function renderFingerprint(){const qs=curvesFor(state.mapCompound),w=measure('fingerprint'),h=Math.max(210,qs.length*46+60),left=87,right=45,top=15,max=Math.max(state.threshold+20,...qs.map(q=>q.cmax)),min=Math.min(0,...qs.map(q=>q.cmax)),x=linear([min,max],[left,w-right]);let b='';for(const tick of ticks([min,max],4)){b+=line(x(tick),top,x(tick),h-42);b+=txt(x(tick),h-25,fmt(tick,0),'text-anchor="middle"');}qs.forEach((q,i)=>{const y=top+i*46;b+=txt(left-9,y+20,q.target,'text-anchor="end"');b+=`<rect x="${Math.min(x(0),x(q.cmax))}" y="${y+6}" width="${Math.abs(x(q.cmax)-x(0))}" height="22" rx="3" fill="${color(q.target)}" opacity="${active(q)?1:.4}" ${tip(`${q.target}: ${fmt(q.cmax,3)}; ${activityStatus(q)}`)}/>`;b+=txt(x(q.cmax)+6,y+21,fmt(q.cmax,1),'class="strong-label"');});b+=line(x(state.threshold),top,x(state.threshold),h-42,'#96a4b6','stroke-dasharray="3 3"');b+=txt((left+w-right)/2,h-5,'Cmax (corrected response units)','text-anchor="middle" class="axis-title"');$('fingerprint').innerHTML=svg(w,h,b,`${state.mapCompound}: Cmax fingerprint by target`);}
function rank(values){const ids=values.map((v,i)=>({v,i})).sort((a,b)=>a.v-b.v),out=[];for(let i=0;i<ids.length;){let j=i;while(j+1<ids.length&&ids[j+1].v===ids[i].v)j++;for(let k=i;k<=j;k++)out[ids[k].i]=(i+j)/2+1;i=j+1;}return out;}
function spearman(a,b){if(a.length<3)return null;const x=rank(a),y=rank(b),xm=x.reduce((a,b)=>a+b,0)/x.length,ym=y.reduce((a,b)=>a+b,0)/y.length;let s=0,sx=0,sy=0;for(let i=0;i<x.length;i++){s+=(x[i]-xm)*(y[i]-ym);sx+=(x[i]-xm)**2;sy+=(y[i]-ym)**2;}return sx&&sy?s/Math.sqrt(sx*sy):null;}
function renderCorrelation(){const d=state.data;let b='<table class="correlation-table"><thead><tr><th>Target</th>'+d.targets.map(t=>`<th style="text-align:center">${esc(t)}</th>`).join('')+'</tr></thead><tbody>';for(const t of d.targets){b+=`<tr><th>${esc(t)}</th>`;for(const u of d.targets){const pairs=d.compounds.map(c=>{const qs=curvesFor(c);return [qs.find(q=>q.target===t),qs.find(q=>q.target===u)];}).filter(p=>p[0]&&p[1]),r=spearman(pairs.map(p=>p[0].cmax),pairs.map(p=>p[1].cmax));const hue=r==null?'#f4f6f9':r>=0?`rgba(36,101,203,${Math.abs(r)*.23})`:`rgba(205,125,55,${Math.abs(r)*.23})`;b+=`<td style="background:${hue}">${r==null?'—':fmt(r,2)}<small>n = ${pairs.length}</small></td>`;}b+='</tr>';}b+='</tbody></table>';$('correlation').innerHTML=b;}
function renderResults(){const mode=$('sourceMode').value,term=$('search').value.trim().toLowerCase(),target=$('targetFilter').value,only=$('activeOnly').checked;const qs=state.data.curves.filter(q=>(!mode||q.report?.source_mode===mode)&&(!term||q.compound.toLowerCase().includes(term))&&(!target||q.target===target)&&ec50Matches(q)&&(!only||active(q)));$('resultCount').textContent=`${qs.length} compound–target rows · ${qs.filter(active).length} meet ${activityRule()}. All-parameter CSV contains every pair; active CSV uses the selected Cmax and EC50 criteria. Search and target display filters do not limit exports.`;let b='<table><thead><tr>'+['Compound','Role','Target','Source classification','Activity','Cmax','Cmax basis','Reported EC50 (µM)','Reported EC50 range','Refit EC50 (µM)','Hill','S0','Sinf','Amplitude','Refit R²','RMSE','Source Valid','Source R²','Source QC','Refit limitations'].map(h=>`<th>${h}</th>`).join('')+'</tr></thead><tbody>';for(const q of qs){const f=q.fit||{},r=q.report||{};b+=`<tr><td><button class="compound-link" data-compound="${esc(q.compound)}" data-target="${esc(q.target)}">${esc(q.compound)}</button></td><td>${q.is_reference?'Positive reference':'Library compound'}</td><td>${esc(q.target)}</td><td>${esc(r.source_mode||'Not reported')}</td><td><span class="pill ${active(q)?'':'neutral'}">${esc(activityStatus(q))}</span></td><td class="num">${fmt(q.cmax,2)}</td><td>${esc(q.cmax_basis)}</td><td class="num">${esc(ecText(q).replace(' µM',''))}</td><td>${esc(ecRangeLabel(q))}</td><td class="num">${sig(f.ec50)}</td><td class="num">${fmt(f.hill)}</td><td class="num">${fmt(f.s0)}</td><td class="num">${fmt(f.sinf)}</td><td class="num">${fmt(f.amplitude)}</td><td class="num">${fmt(f.r2,3)}</td><td class="num">${fmt(f.rmse)}</td><td>${esc(r.source_valid||'not reported')}</td><td class="num">${fmt(r.source_r2,3)}</td><td class="qc-cell">${esc(r.source_qc||'none')}</td><td class="qc-cell">${esc(q.fit_flags.join('; ')||'Within range; inspect source QC')}</td></tr>`;}b+='</tbody></table>';$('resultsTable').innerHTML=b;}
function renderMethods(){const d=state.data;if(!d)return;$('experimentDetails').innerHTML=`<p><strong>${d.compounds.length} compounds · ${d.targets.length} targets</strong><br>${d.curves.length} curves · ${fmt(d.wells_total,0)} sample wells<br>${d.wells_excluded} masked/ignored wells excluded</p><h3>Cmax definitions</h3><p>${d.cmax_bases.map(esc).join('<br>')}</p><h3>Source files</h3><p style="overflow-wrap:anywhere">${d.files.map(esc).join('<br><br>')}</p>${d.notes.length?'<h3>Data notes</h3><p>'+d.notes.map(esc).join('<br>')+'</p>':''}`;}
