sample().then(()=>{const requestedView=new URLSearchParams(location.search).get('view');if(requestedView&&titles[requestedView])setView(requestedView);});

function renderSourceSummary(){const qs=analysisCurves();if(state.study==='EXP26003438'){$('sourceSummary').innerHTML='<section class="panel"><h2>Source parameter report</h2><p>143 library compounds are labeled “increasing” in the supplied parameter report. This is the source classification, separate from the adjustable Cmax / EC50 criteria. Its parameter values remain in the separate report because the workbook has no replicate or plate identifiers to tie each fit to one of these four curves.</p></section>';return;}if(!qs.some(q=>q.report?.source_mode)){$('sourceSummary').innerHTML='';return;}const modes=[...new Set(qs.map(q=>q.report?.source_mode||'Not reported'))].sort();$('sourceSummary').innerHTML='<section class="panel"><h2>Source classifications</h2><p class="section-note">GDS Data Mode labels are retained separately from the adjustable Cmax/EC50 criteria.</p><div class="source-counts">'+modes.map(m=>`<span><strong>${qs.filter(q=>(q.report?.source_mode||'Not reported')===m).length}</strong> ${esc(m)}</span>`).join('')+'</div></section>';}
async function renderInstrumentReadings(){if(state.study!=='EXP26003438'){$('instrumentReadings').innerHTML='<section class="panel">Separate instrument CSVs are available for EXP26003438. Select that experiment above. The current experiment retains raw measurements in Raw plate QC.</section>';return;}if(!state.instrument){$('instrumentReadings').innerHTML='<section class="panel">Loading instrument readings…</section>';try{const r=await fetch('./cyclind1-instrument.json');if(!r.ok)throw new Error('Instrument readings unavailable');state.instrument=await r.json();}catch(e){$('instrumentReadings').textContent=e.message;return;}}if(state.view==='instrumentReadings')AtlasInstrumentView.render({host:'instrumentReadings',data:state.instrument});}
function renderPotencyMap(){const useRefit=!analysisCurves().some(q=>q.report?.ec50>0),qs=analysisCurves().map(q=>useRefit?{...q,original:q,report:{ec50:q.fit?.ec50,qualifier:'='}}:q).filter(q=>Number.isFinite(q.report?.ec50)&&q.report.ec50>0),w=measure('pca'),h=390,left=62,right=22,top=20,bottom=55;if(!qs.length){$('pca').innerHTML='<p>No positive reported EC50 values are available.</p>';return;}const xd=range(qs.map(q=>Math.log10(q.report.ec50)),.08),yd=range([state.threshold,...qs.map(q=>q.cmax)]),x=linear(xd,[left,w-right]),y=linear(yd,[h-bottom,top]);let b='';for(const t of ticks(xd,5)){b+=line(x(t),top,x(t),h-bottom);b+=txt(x(t),h-bottom+18,sig(10**t),'text-anchor="middle"');}for(const t of ticks(yd,5)){b+=line(left,y(t),w-right,y(t));b+=txt(left-9,y(t)+4,fmt(t,0),'text-anchor="end"');}b+=line(left,y(state.threshold),w-right,y(state.threshold),'#8b99ac','stroke-dasharray="4 4"');for(const q of qs){const px=x(Math.log10(q.report.ec50)),py=y(q.cmax),qual=q.report.qualifier||'=',bound=/[<>≥≤]/.test(qual),selected=q.compound===state.mapCompound;b+=`<circle cx="${px}" cy="${py}" r="${selected?6:3.5}" fill="${active(q.original||q)?color(q.target):'#adb8c8'}" stroke="${selected?'#172b45':'#fff'}" data-map-compound="${esc(q.compound)}" tabindex="0" role="button" aria-label="Select ${esc(q.compound)}" ${tip(q.compound+'; '+(useRefit?'independent 4PL':'reported')+' EC50 '+ecText(q)+'; Cmax '+fmt(q.cmax,2))}/>`;if(bound)b+=txt(px+5,py+3,/[>≥]/.test(qual)?'›':'‹','style="font-size:11px"');}b+=txt((left+w-right)/2,h-8,(useRefit?'Independent 4PL':'Reported')+' EC50 (µM; logarithmic scale)','text-anchor="middle"');b+=`<text transform="translate(14 ${(top+h-bottom)/2}) rotate(-90)" text-anchor="middle">Cmax</text>`;$('pca').innerHTML=svg(w,h,b,'Reported EC50 versus Cmax');$('mapLegend').textContent='Colored: meets selected criteria · Grey: does not meet criteria · › / ‹: reported bound';$('pcaNote').textContent=qs.length+(useRefit?' independent 4PL EC50 estimates plotted; inspect fit limitations and tested dose bounds.':' reported EC50 values plotted.')+' Qualified estimates remain bounds; points do not include replicate uncertainty. A single assay does not support a target-profile PCA. Click a point to inspect its curve.';}
async function renderSourceParameters(){const host=$('sourceReport');if(state.study!=='EXP26003438'){host.innerHTML='<section class="panel">This additional source report belongs to EXP26003438.</section>';return;}if(!state.sourceParameters){const r=await fetch('./cyclind1-source-parameters.json');if(!r.ok){host.textContent='Source parameter report unavailable.';return;}state.sourceParameters=await r.json();}const all=state.sourceParameters;host.innerHTML=`<section class="panel"><h2>Source parameter report — replicate assignment unavailable</h2><p>This file is retained separately from the four reconstructed curves because it contains no plate or biological replicate identifiers. Per the confirmed layout, its workbook is the no-inhibitor condition; reported Cmax/EC50 do not determine activity calls in the per-replicate raw-ratio analysis.</p><div class="toolbar"><label>Source classification<select id="unassignedMode"><option value="increasing">Increasing (143 library compounds)</option><option value="">All source classifications</option><option>increasing (weakly active)</option><option>inactive</option><option>decreasing (weakly active)</option></select></label><label class="check"><input id="unassignedReference" type="checkbox">Include positive reference</label><button id="exportUnassigned" class="secondary">Export source parameters CSV</button></div><p id="unassignedCount"></p><div id="unassignedTable" class="table-scroll"></div></section>`;function update(){const mode=$('unassignedMode').value,ref=$('unassignedReference').checked,qs=all.filter(q=>(!mode||q.source_mode===mode)&&(ref||!q.is_reference));$('unassignedCount').textContent=qs.length+' source parameter rows shown. Positive reference is separate from library counts.';$('unassignedTable').innerHTML='<table><thead><tr>'+['Compound','Role','Source classification','Reported Cmax','Reported EC50 (µM)','Source S0','Source Sinf','Source R²','Source wells','Source QC'].map(h=>'<th>'+h+'</th>').join('')+'</tr></thead><tbody>'+qs.map(q=>`<tr><td>${esc(q.compound)}</td><td>${q.is_reference?'Positive reference':'Library compound'}</td><td>${esc(q.source_mode)}</td><td>${fmt(q.cmax)}</td><td>${esc(q.qualifier)} ${sig(q.ec50)}</td><td>${fmt(q.source_s0)}</td><td>${fmt(q.source_sinf)}</td><td>${fmt(q.source_r2,3)}</td><td>${fmt(q.source_wells,0)}</td><td>${esc(q.source_qc)}</td></tr>`).join('')+'</tbody></table>';}$('unassignedMode').addEventListener('change',update);$('unassignedReference').addEventListener('change',update);$('exportUnassigned').addEventListener('click',()=>{const keys=['compound','is_reference','source_mode','cmax','ec50','qualifier','source_s0','source_sinf','source_r2','source_wells','source_qc','source_custom_settings'];download(new Blob(['﻿'+keys.join(',')+'\n'+all.map(q=>keys.map(k=>'"'+String(q[k]??'').replaceAll('"','""')+'"').join(',')).join('\n')],{type:'text/csv'}),'unassigned_source_parameters.csv');});update();}
async function renderNormalizationAudit(){const host=$('normalizationAudit');if(state.study!=='EXP26003438'){host.innerHTML='<section class="panel">This normalization check was performed on the EXP26003438 well export.</section>';return;}if(!state.normalization){const r=await fetch('./normalization-audit.json');if(!r.ok){host.textContent='Normalization audit unavailable.';return;}state.normalization=await r.json();}const rows=state.normalization,max=Math.max(...rows.map(a=>a.regressions.ratio_control_median.max_abs_residual));host.innerHTML=`<section class="panel"><h2>GDS normalization follows the ratio</h2><p>For every numeric normalized well in all 24 supplied B plates, the exported response is reproduced by:</p><p class="formula">100 × (ratio − plate median no-HaloTag ratio) / (plate median DMSO ratio − plate median no-HaloTag ratio)</p><p>QC Layer Raw = 1,000 × exported ratio, within stored floating-point precision. The ratio is acceptor 645 / donor 460. This is the HaloTag acceptor emission divided by NanoLuc donor emission, not donor NanoLuc intensity alone.</p><p><strong>7,392 numeric wells checked · maximum absolute reconstruction difference ${max.toPrecision(3)} response units.</strong> This is direct numerical evidence for this export; it does not verify other GDS experiments or explain the unassigned parameter report.</p><div class="toolbar"><label>Plate<select id="normalizationPlate">${rows.map(a=>`<option>${esc(a.plate)}</option>`).join('')}</select></label></div><div id="normalizationPlot" class="plot"></div><p class="section-note">Each point is an exported well. The straight line shows the independently reconstructed control-normalized ratio.</p><div class="table-scroll"><table><thead><tr><th>Plate</th><th>N</th><th>Median DMSO ratio</th><th>Median no-HaloTag ratio</th><th>Ratio linear R²</th><th>NanoLuc donor linear R²</th><th>Maximum reconstruction difference</th></tr></thead><tbody>${rows.map(a=>`<tr><td>${esc(a.plate)}</td><td>${a.n}</td><td>${a.median_dmso_ratio.toPrecision(6)}</td><td>${a.median_noht_ratio.toPrecision(6)}</td><td>${a.regressions.exported_ratio.r2.toFixed(10)}</td><td>${a.regressions.donor.r2.toFixed(4)}</td><td>${a.regressions.ratio_control_median.max_abs_residual.toExponential(3)}</td></tr>`).join('')}</tbody></table></div></section>`;function plot(){const a=rows.find(a=>a.plate===$('normalizationPlate').value),ps=a.points,w=measure('normalizationPlot'),h=310,l=65,r=25,t=20,bot=48,xd=range(ps.map(p=>p.ratio)),yd=range(ps.map(p=>p.corrected)),x=linear(xd,[l,w-r]),y=linear(yd,[h-bot,t]);let b='';for(const k of ticks(xd,5)){b+=line(x(k),t,x(k),h-bot);b+=txt(x(k),h-bot+18,sig(k),'text-anchor="middle"');}for(const k of ticks(yd,5)){b+=line(l,y(k),w-r,y(k));b+=txt(l-9,y(k)+4,fmt(k,0),'text-anchor="end"');}for(const p of ps)b+=`<circle cx="${x(p.ratio)}" cy="${y(p.corrected)}" r="2.5" fill="#2465cb" opacity=".55" ${tip(p.well+': ratio '+p.ratio+'; exported response '+p.corrected)}/>`;const pred=v=>100*(v-a.median_noht_ratio)/(a.median_dmso_ratio-a.median_noht_ratio);b+=line(x(xd[0]),y(pred(xd[0])),x(xd[1]),y(pred(xd[1])),'#d07836','stroke-width="1.5"');b+=txt((l+w-r)/2,h-6,'Exported acceptor / donor ratio','text-anchor="middle"');b+=`<text transform="translate(15 ${(t+h-bot)/2}) rotate(-90)" text-anchor="middle">GDS normalized response</text>`;$('normalizationPlot').innerHTML=svg(w,h,b,'Exported ratio versus GDS normalized response');}$('normalizationPlate').addEventListener('change',plot);plot();}
async function renderLayoutAudit(){const host=$('layoutAudit');if(state.study!=='EXP26003438'){host.innerHTML='<section class="panel">This layout audit belongs to EXP26003438.</section>';return;}if(!state.layoutAudit){const r=await fetch('./layout-audit.json');if(!r.ok){host.textContent='Layout audit unavailable.';return;}state.layoutAudit=await r.json();}const a=state.layoutAudit;host.innerHTML=`<section class="panel"><h2>Verified from all supplied workbook sheets</h2><p>Both Header and Results sheets were checked in both files.</p><p><strong>Well export Header:</strong> ${esc(a.well_export_description)}</p><p><strong>Parameter export Header:</strong> ${esc(a.parameter_export_description)}</p><p>The well export contains 24 B plates. The supplied workbook exports map B plates; your confirmation establishes that each same-number A/B pair contains the same compounds and doses, with B adding 25 µM CypA inhibitor. Compound IDs and dose labels for A are therefore assigned from its paired B layout and clearly marked as based on your confirmation.</p><p><strong>01B versus 02B:</strong> Different plate numbers contain their own compound sets. Within each plate number, the matched A/B plates contain the same compounds; B adds the inhibitor. The B export shows 12 library compounds + reference on 01B and 13 + reference on 02B. Technical duplicates are within each plate, in columns 2–11 and 12–21.</p><div class="toolbar"><label>Plate<select id="layoutPlate">${a.plates.map(p=>`<option>${esc(p.plate)}</option>`).join('')}</select></label></div><div id="layoutDetails"></div><h3>All B-plate coverage</h3><div class="table-scroll"><table><thead><tr><th>Plate</th><th>Library IDs</th><th>Reference IDs</th><th>Total IDs</th></tr></thead><tbody>${a.plates.map(p=>`<tr><td>${esc(p.plate)}</td><td>${p.library_count}</td><td>1</td><td>${p.compound_count}</td></tr>`).join('')}</tbody></table></div></section>`;function show(){const p=a.plates.find(p=>p.plate===$('layoutPlate').value);$('layoutDetails').innerHTML='<table><thead><tr><th>Row</th><th>Compound ID</th><th>Dose levels</th><th>Source wells</th></tr></thead><tbody>'+p.assignments.map(a=>`<tr><td>${esc(a.row)}</td><td>${esc(a.compounds.join('; '))}</td><td>${a.doses.length}</td><td>${a.wells}</td></tr>`).join('')+'</tbody></table>';}$('layoutPlate').addEventListener('change',show);show();}
